(async () => {
  const url = 'http://127.0.0.1:8765/greenhouse_2026-05-22/anthropic/jobs/5023394008.html';
  const html = await (await fetch(url)).text();
  const parsed = new DOMParser().parseFromString(html, 'text/html');
  // Find the apply form
  const form = parsed.querySelector('form');
  if (!form) return { error: 'no form in static html', htmlBytes: html.length };
  const formHtml = form.outerHTML;
  // Replace body with form, then nuke all scripts to keep React from re-mounting
  document.body.innerHTML = formHtml;
  document.querySelectorAll('script').forEach(s => s.remove());
  // Verify
  const liveForm = document.querySelector('form');
  const inputs = Array.from(document.querySelectorAll('input, select, textarea, button')).map(el => ({
    tag: el.tagName.toLowerCase(),
    type: el.type || null,
    id: el.id || null,
    name: el.name || null,
    ariaLabel: el.getAttribute('aria-label'),
    placeholder: el.placeholder || null,
    text: el.tagName === 'BUTTON' ? el.textContent.trim().slice(0, 60) : null,
    accept: el.accept || null,
  }));
  return {
    formInjected: !!liveForm,
    formAction: liveForm?.action || null,
    formMethod: liveForm?.method || null,
    inputCount: inputs.length,
    inputs,
  };
})()

